"""Sim-to-real `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys

NAMES = {"ob": "Online Boutique", "ss": "Sock Shop"}


def cell(m: dict) -> str:
    lo, hi = m["ci95"]
    return f"{m['value']:.3f} [{lo:.3f}, {hi:.3f}]"


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    t, tr = r["tested_on"], r["trained_on"]
    out = [
        "<!-- Generated by packages/sati/sati/rca/simtoreport.py from the training workflow. Do not edit by hand. -->\n",
        "# Sim-to-real — trained on Kaal, tested zero-shot on RCAEval (RP-24)\n",
        f"The ranker learned only from {tr['n']:,} synthetic Kaal incidents (seed {tr['seed']}). Here it ranks the "
        f"services of real fault-injection cases from RCAEval (revision `{t['revision'][:12]}`) with no training on "
        "them: " + ", ".join(f"{NAMES.get(s, s)} {n}" for s, n in t["cases"].items()) + " cases. "
        + " ".join(f"Excluded: {v}." for v in t["excluded"].values()) + "\n",
        "| System | Ranker | RCA@1 [95% CI] | RCA@3 [95% CI] |",
        "|---|---|---:|---:|",
    ]
    for system, rankers in r["test"].items():
        for name, m in rankers.items():
            label = f"**{name}**" if name.startswith("katyayani") else name
            out.append(f"| {NAMES.get(system, system)} | {label} | {cell(m['rca@1'])} | {cell(m['rca@3'])} |")
    out += [
        "",
        "## How to read this\n",
        "- On Kaal's own test splits, the same ranker scores about 0.998 ([katyayani-kaal.md](katyayani-kaal.md)). "
        "The difference between that and this table is the simulation-to-real gap, which is RP-24's real result.",
        "- The call graphs are authored from each project's published architecture, not observed. Checking them "
        "against RCAEval's own traces is the next step. A wrong edge here hurts the zero-shot ranker and not the "
        "baselines.",
        "- Katyayani trained on RCAEval itself is the reference: [sati-rca.md](sati-rca.md), leave one system out.",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
